from p"/var/home/david/dev/dewy-lang/tools/sloppy_core/benchmark_harness.jo" import clock
main=()=>{
let xs=fill(1.0 65536)
let start=clock()
loop i in [0..1024) {xs[1..3) .+= 1.0}
let elapsed=clock()-start
assert(xs[0] =? 1.0 and xs[1] =? 1025.0 and xs[2] =? 1025.0 and xs[3] =? 1.0)
printl(elapsed)
return 0
}
